require_once __DIR__ . '/../../includes/bootstrap.php';$user=require_role('hospital_admin');$stmt=db()->prepare("SELECT * FROM organizations WHERE owner_user_id=? ORDER BY CASE WHEN approval_status='approved' THEN 0 ELSE 1 END, id DESC LIMIT 1");$stmt->execute([$user['id']]);$org=$stmt->fetch();if(!$org){http_response_code(403);$pageTitle='Provider application';require __DIR__.'/../../includes/header.php';?><section class="page-intro"><span class="eyebrow">PROVIDER ACCESS</span><h1>No organization found</h1><p>Your account is signed in, but there is no organization linked to it. Please contact CareBridge support.</p><a class="button" href="<?= e(url('logout.php')) ?>">Sign out</a></section><?php require __DIR__.'/../../includes/footer.php';exit;}if(($org['approval_status']??'pending')!=='approved'){$pageTitle='Provider application status';require __DIR__.'/../../includes/header.php';?><section class="dashboard-welcome"><div><span class="eyebrow">PROVIDER APPLICATION</span><h1><?= e($org['name']) ?></h1><p>Your email is verified. Your healthcare organization is awaiting platform/government approval.</p></div><span class="status status-pending">Pending review</span></section><section class="form-panel"><h2>What happens next?</h2><p>CareBridge will enable the provider workspace after your organization is approved. You do not need to register again.</p><p><strong>Application reference:</strong> CB-H<?= e(str_pad((string)$org['id'],6,'0',STR_PAD_LEFT)) ?></p><a class="button button-secondary" href="<?= e(url('logout.php')) ?>">Sign out</a></section><?php require __DIR__.'/../../includes/footer.php';exit;}
$oid=(int)$org['id'];$q=db()->prepare('SELECT COUNT(*) FROM appointments WHERE organization_id=?');$q->execute([$oid]);$totalAppointments=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*) FROM appointments WHERE organization_id=? AND status IN ('requested','confirmed','checked_in')");$q->execute([$oid]);$activeTickets=(int)$q->fetchColumn();$q=db()->prepare('SELECT COUNT(DISTINCT patient_user_id) FROM appointments WHERE organization_id=?');$q->execute([$oid]);$patients=(int)$q->fetchColumn();$q=db()->prepare("SELECT a.id,a.starts_at,a.reason,a.status,u.full_name,u.email,p.patient_code,d.name department_name FROM appointments a JOIN users u ON u.id=a.patient_user_id LEFT JOIN patient_profiles p ON p.user_id=u.id LEFT JOIN departments d ON d.id=a.department_id WHERE a.organization_id=? ORDER BY a.created_at DESC LIMIT 8");$q->execute([$oid]);$recent=$q->fetchAll();$pageTitle='Hospital workspace';require __DIR__.'/../../includes/header.php';
?>
<section class="dashboard-welcome"><div><span class="eyebrow">VERIFIED PROVIDER WORKSPACE</span><h1><?= e($org['name']) ?></h1><p>Manage patient appointments, ticket queues, and department setup.</p></div><span class="status status-success">Approved provider</span></section>
<div class="hospital-tools"><a href="<?= e(url('hospital/patients.php')) ?>"><span>♙</span><strong>Patient management</strong><small>View patients and appointment tickets</small></a><a href="<?= e(url('hospital/appointments.php')) ?>"><span>◷</span><strong>Appointments & queue</strong><small>Confirm, check in, and close tickets</small></a><a href="<?= e(url('hospital/departments.php')) ?>"><span>▦</span><strong>Departments</strong><small>Manage services available for booking</small></a><a href="<?= e(url('hospital/records.php')) ?>"><span>✚</span><strong>Clinical records</strong><small>Document consultations and prescriptions</small></a></div>
